//! Hugging Face byte-level BPE tokenizer capability for MLPL extensions.
//!
//! This step delivers file parsing, validation, and the `validate` diagnostic.
//! Encoding, decoding, and typed handles follow in later steps.

mod byte_level;
mod file_source;
mod handles;
mod tokenizer_file;

pub use byte_level::ByteLevelTokenizer;
pub use file_source::validate_value;
pub use handles::{
    close_value, decode_value, encode_value, info_value, load_path_value, load_value,
    token_to_id_value,
};
pub use tokenizer_file::{CONTROL_TOKENS, TokenizerFile};

const METADATA: &str = r#"
[[functions]]
name = "validate"
documentation = "Validate a tokenizer.json and report its vocabulary summary."
returns = "record"
[[functions.arguments]]
name = "request"
type = "record"

[[functions]]
name = "load"
documentation = "Load one tokenizer.json beneath an explicit root."
returns = "native<Tokenizer>"
[[functions.arguments]]
name = "request"
type = "record"

[[functions]]
name = "load_path"
documentation = "Load one tokenizer.json named by an absolute path."
returns = "native<Tokenizer>"
[[functions.arguments]]
name = "path"
type = "string"

[[functions]]
name = "encode"
documentation = "Encode text into an array of token ids."
returns = "array"
[[functions.arguments]]
name = "tokenizer"
type = "native<Tokenizer>"
[[functions.arguments]]
name = "text"
type = "string"

[[functions]]
name = "decode"
documentation = "Decode token ids back into text, keeping control tokens visible."
returns = "string"
[[functions.arguments]]
name = "tokenizer"
    }

    /// Encodes text into token ids.
    ///
    /// Added tokens, which include the control tokens, are matched literally
    /// and isolated before pre-tokenization, so they never merge with
    /// surrounding text.
    ///
    /// # Errors
    ///
    /// Returns a reason when a byte-level fragment is absent from the
    /// vocabulary, which means the file's alphabet is incomplete.
    pub fn encode(&self, text: &str) -> Result<Vec<i64>, String> {
        let mut ids = Vec::new();
        for segment in self.split_on_added_tokens(text) {
            match segment {
                Segment::Added(id) => ids.push(id),
                Segment::Text(text) => self.encode_text(text, &mut ids)?,
            }
        }
        Ok(ids)
    }

    /// Decodes token ids back into text, leaving control tokens visible as
    /// their literal spelling rather than dropping them.
    ///
    /// # Errors
    ///
    /// Returns a reason when an id is absent from the vocabulary or the
    /// decoded bytes are not valid UTF-8.
    pub fn decode(&self, ids: &[i64]) -> Result<String, String> {
        let mut bytes = Vec::new();
        for id in ids {
            let token = self
                .id_to_token
                .get(id)
                .ok_or_else(|| format!("id {id} is not in the vocabulary"))?;
            if self
                .added
                .iter()
                .any(|(content, added)| added == id && content == token)
            {
                // An added token is literal text, not byte-level glyphs.
                bytes.extend_from_slice(token.as_bytes());
                continue;
            }
            for glyph in token.chars() {
                let byte = self.unicode_to_byte.get(&glyph).ok_or_else(|| {
                    format!("token {token} contains a glyph outside the byte-level alphabet")
                })?;
                bytes.push(*byte);
            }
        }
        String::from_utf8(bytes).map_err(|error| format!("decoded bytes are not UTF-8: {error}"))
    }

    /// Looks up one token's id.
    #[must_use]
    pub fn token_to_id(&self, token: &str) -> Option<i64> {
        self.vocab.get(token).copied()
    }
